insert into public.companies(slug,ticker,name,exchange,currency,quote_unit,price_decimals,market_data_symbol,market_data_multiplier,country,sector)
select slug,ticker,name,exchange,currency,quote_unit,price_decimals,market_data_symbol,market_data_multiplier,country,sector from payload
on conflict (slug) do update set
 ticker=excluded.ticker,name=excluded.name,exchange=excluded.exchange,currency=excluded.currency,quote_unit=excluded.quote_unit,
 price_decimals=excluded.price_decimals,market_data_symbol=excluded.market_data_symbol,market_data_multiplier=excluded.market_data_multiplier,
 country=excluded.country,sector=excluded.sector,updated_at=now();

