insert into public.market_prices(company_id,price,as_of,source)
select c.id,p.price,p.as_of,p.source
from payload p join public.companies c using(slug)
where not exists (
  select 1 from public.market_prices mp
  where mp.company_id = c.id and mp.price = p.price and mp.as_of = p.as_of and mp.source = p.source
);
